// in your package
type Pinger interface {
	Ping(ctx context.Context) error
}

// in a library you do not control
type Client struct{ /* ... */ }
func (c *Client) Ping(ctx context.Context) error { /* ... */ }

// this just works
var p Pinger = &Client{}

type MyErr struct{}
func (e *MyErr) Error() string { return "boom" }

func find() *MyErr {      // concrete return type - the mistake
	return nil
}

func run() error {
	return find()         // nil *MyErr -> non-nil error
}

if err := run(); err != nil {
	// TAKEN. err is (*MyErr, nil)
	fmt.Println(err)      // prints boom
}

type Reader interface { Read(p []byte) (n int, err error) }
type Writer interface { Write(p []byte) (n int, err error) }

type ReadWriter interface {
	Reader
	Writer
}

type Status int

func (s Status) String() string {
	switch s {
	case 0:
		return "pending"
	case 1:
		return "running"
	}
	return "unknown"
}

fmt.Printf("%v\n", Status(1))   // running, not 1
